const btnRect = btn.getBoundingClientRect();
if (btnRect.width < 24 || btnRect.height < 24) return false;

// Accessible name starts with visible label (WCAG 2.5.3 Label in Name)
const ariaLabel = btn.getAttribute('aria-label') || '';
if (!ariaLabel.startsWith('View data table')) return false;

// Focus indicator on chart button (WCAG 2.4.7 Focus Visible)
btn.focus();
const btnStyle = window.getComputedStyle(btn);
const hasOutline = btnStyle.outlineStyle !== 'none' && parseFloat(btnStyle.outlineWidth) >= 2;
const hasShadow = btnStyle.boxShadow && btnStyle.boxShadow !== 'none';
if (!hasOutline && !hasShadow) return false;
btn.blur();

