// Close button focus indicator
closeBtn.focus();
const closeStyle = window.getComputedStyle(closeBtn);
const closeHasOutline = closeStyle.outlineStyle !== 'none' && parseFloat(closeStyle.outlineWidth) >= 2;
closeBtn.blur();
